#include "ui/DeviceCenterModel.h"
#include <algorithm>
namespace jeff::daw {void DeviceCenterModel::setAudio(AudioStatus s,const std::string&m){audio=s==AudioStatus::ready?"Audio ready":m.empty()?"Choose another audio device and retry.":m+" Choose another device and retry.";}void DeviceCenterModel::setMidi(const std::vector<DeviceIdentity>&dev,const std::vector<std::string>&sel){data.clear();for(auto&d:dev){bool s=std::find(sel.begin(),sel.end(),d.stableId)!=sel.end();data.push_back({d.stableId,d.name,s?"Connected":"Available",s?"Disconnect":"Connect",s});}}void DeviceCenterModel::setDiagnostics(std::uint64_t d,std::uint64_t u){dropCount=d;underrunCount=u;}std::string DeviceCenterModel::diagnostics()const{return"MIDI queue drops: "+std::to_string(dropCount)+" | Audio underruns: "+std::to_string(underrunCount);}}
